function SmearScreen(self, lifetime, time, inclt, maxlt, del_immediately)
    inclt = inclt or 0
    maxlt = maxlt or 9999
    task.New(self, function()
        local _uv1, _uv2, _uv3, _uv4 = { [3] = 0.5 }, { [3] = 0.5 }, { [3] = 0.5 }, { [3] = 0.5 }
        local w = lstg.world
        _uv1[1], _uv1[2] = w.l, w.t
        _uv2[1], _uv2[2] = w.r, w.t
        _uv3[1], _uv3[2] = w.r, w.b
        _uv4[1], _uv4[2] = w.l, w.b
        _uv1[4], _uv1[5] = WorldToScreen(w.l, w.t)
        _uv2[4], _uv2[5] = WorldToScreen(w.r, w.t)
        _uv3[4], _uv3[5] = WorldToScreen(w.r, w.b)
        _uv4[4], _uv4[5] = WorldToScreen(w.l, w.b)
        local objs = {}
        local maxk = 1
        local k = 1
        for i = 1, time do
            local name = "SmearScreen_EFF" .. k
            CreateRenderTarget(name)
            table.insert(objs, New(Class(object, {
                init = function(unit)
                    unit.layer = LAYER.BG - 10
                    unit.colli = false
                end,
                frame = function(unit)
                    if unit.timer >= lifetime then
                        Del(unit)
                    end
                end,
                render = function(unit)
                    if unit.timer == 1 and lifetime >= 1 then
                        PushRenderTarget(name)
                        RenderClear(Color(0, 0, 0, 0))
                    end
                end
            }, true)))
            table.insert(objs, New(Class(object, {
                init = function(unit)
                    unit.layer = LAYER.TOP - 1 - i * 0.01
                    unit.colli = false
                end,
                frame = function(unit)
                    if unit.timer >= lifetime then
                        Del(unit)
                    end
                end,
                render = function(unit)
                    if lifetime >= 1 then
                        if unit.timer == 1 then
                            PopRenderTarget(name)
                        end
                        local _color = Color(max(1 - (unit.timer - 1) / lifetime, 0) * 255, 255, 255, 255)
                        _uv1[6] = _color
                        _uv2[6] = _color
                        _uv3[6] = _color
                        _uv4[6] = _color
                        RenderTexture(name, "mul+add", _uv1, _uv2, _uv3, _uv4)
                    end
                end
            }, true)))

            lifetime = min(lifetime + inclt, maxlt)
            k = k + 1
            if i % (lifetime + 1) == 0 then
                k = 1
            end
            maxk = max(maxk, k)
            task.Wait()
        end
        if del_immediately then
            sp:UnitListUpdate(objs)
            for _, o in ipairs(objs) do
                object.RawDel(o)
            end
        else
            task.Wait(lifetime)
        end
        for i = 1, maxk do
            RemoveResource("stage", 1, "SmearScreen_EFF" .. i)
        end
    end)
end

