local PASS_CONTROL_UNIT
---咏唱解除机制
local function ForcePassSpell(open)
    if IsValid(PASS_CONTROL_UNIT) then
        Del(PASS_CONTROL_UNIT)
    end
    if open then
        PASS_CONTROL_UNIT = New(Class(object, {
            frame = task.Do,
            init = function(self)
                self.layer = LAYER.PLAYER - 1
                self.group = GROUP.GHOST
                self.alpha = 0
                task.New(self, function()
                    while true do
                        if player.death >= 89 then
                            lstg.var.dead = lstg.var.dead - 1
                            player.lock = true
                            for _, b in ipairs(boss_group) do
                                task.Clear(b)
                            end
                            for i = 1, 60 do
                                for bgm in pairs(ext.music) do
                                    SetBGMVolume(bgm, 1 - i / 60)
                                end
                                for _, b in ipairs(boss_group) do
                                    b.timer = b.timer - 1
                                end
                                self.alpha = i / 60
                                task.Wait()
                            end
                            local t = boss_group[1].t1 - boss_group[1].timer - 60
                            for bgm, p in pairs(ext.music) do
                                p.timer = p.timer + t
                                SetBGMVolume(bgm, 1)
                            end
                            for _ = 1, t do
                                task.Do(stage.current_stage)
                            end
                            task.New(self, function()
                                for i = 59, 0, -1 do
                                    self.alpha = i / 60
                                    task.Wait()
                                end
                            end)
                            ext.FastMusic()
                            New(WhiteScreen)
                            for _, b in ipairs(boss_group) do
                                object.Kill(b)
                            end
                            player.lock = false
                        end
                        task.Wait()
                    end
                end)
            end,
            render = function(self)
                local b = min(self.timer / 90, 1)
                for i = 1, 16 do
                    SetImageState('bossring3' .. i, "add+add", b * 150, sp:HSVtoRGB(35, 0.9, 1))
                end
                local t = task.SetMode[2](self.alpha)
                misc.RenderRing('bossring3', player.x, player.y, 150 + t * 100, 190 + t * 100, self.timer * 2, 48, 16)
                SetImageState("Sakura2", "mul+add", t * 200, 250, 128, 114)
                Render("Sakura2", player.x, player.y, self.timer * 2, 1 - t * 0.3)
            end
        }, true))
    end
end
_G.ForcePassSpell=ForcePassSpell

local PulseScreen = Class(object, {
    init = function(self, layer, col, blend, fade_in, stay, fade_out, mode)
        self.layer = layer or LAYER.TOP
        self.group = GROUP.GHOST
        self.blend = blend or ""
        self.mode = mode or "world"
        self._r, self._g, self._b = unpack(col or { 255, 255, 255 })
        fade_in = fade_in or 0
        stay = stay or 0
        fade_out = fade_out or 0
        self.lifetime = fade_in + stay + fade_out
        if fade_in > 0 then
            self._a = 0
        else
            self._a = 255
        end
        task.New(self, function()
            for i = 1, fade_in do
                self._a = i / fade_in * 255
                task.Wait()
            end
            task.Wait(stay)
            for i = 1, fade_out do
                self._a = 255 - i / fade_out * 255
                task.Wait()
            end
        end)

    end,
    frame = function(self)
        task.Do(self)
        if self.timer >= self.lifetime then
            object.RawDel(self)
        end
    end,
    render = function(self)
        SetImageState("white", self.blend, self._a, self._r, self._g, self._b)
        if self.mode == "world" then
            RenderRect("white", lstg.world.l, lstg.world.r, lstg.world.b, lstg.world.t)
        else
            RenderRect("white", 0, screen.width, 0, screen.height)
        end
    end
})
function NewPulseScreen(layer, col, blend, fade_in, stay, fade_out, mode)
    return New(PulseScreen, layer, col, blend, fade_in, stay, fade_out, mode)
end

local SimpleServant = Class(object)
function SimpleServant:init(x, y, a, r, g, b, scale, event, frame)
    object.init(self, x, y, GROUP.INDES, LAYER.ENEMY)
    self.colli = false
    self.img = "servant"
    self.frame_func = frame or load("")
    self._a, self._r, self._g, self._b = a, r, g, b
    self._blend = "mul+add"
    self.hscale = scale
    self.vscale = scale
    self.omiga = ran:Float(2, 3) * ran:Sign()
    function self:FadeIn(time, mode)
        task.New(self, function()
            local nowa = self._a
            mode = mode or 0
            for i = 1, time do
                self._a = nowa + (255 - nowa) * task.SetMode[mode](i / time)
                task.Wait()
            end
        end)
    end
    function self:FadeOut(time, mode)
        task.New(self, function()
            local nowa = self._a
            mode = mode or 0
            for i = 1, time do
                self._a = nowa * task.SetMode[mode](1 - i / time)
                task.Wait()
            end
        end)
    end
    if event then
        event(self)
    end
end
function SimpleServant:frame()
    task.Do(self)
    self:frame_func()
end
function SimpleServant:render()
    SetImageState(self.img, self._blend, self._a, self._r, self._g, self._b)
    DefaultRenderFunc(self)
end
_G.SimpleServant = SimpleServant
function NewSimpleServant(x, y, a, r, g, b, scale, event, frame)
    return New(SimpleServant, x, y, a, r, g, b, scale, event, frame)
end

function ParticleLaserBent(pR, pG, pB, x, y, index, length, w, v, a, ...)
    local l = Create.laser_changeangle(x, y, index, length, w, v, a, ...)
    l.particle = {}
    l.pcol = { pR, pG, pB }
    function l:frame_new()
        bent_laser.frame(self)
        if self.timer < 90 then
            local _a = ran:Float(0, 360)
            local _v = ran:Float(3, 6)
            table.insert(self.particle, {
                x = self.x, y = self.y,
                vx = cos(_a) * _v, vy = sin(_a) * _v,
                alpha = ran:Float(200, 250), timer = 0,
                r = self.pcol[1], g = self.pcol[2], b = self.pcol[3]
            })
        end
        local p
        for i = #self.particle, 1, -1 do
            p = self.particle[i]
            p.x = p.x + p.vx
            p.y = p.y + p.vy
            p.vx = p.vx - p.vx * 0.04
            p.vy = p.vy - p.vy * 0.04
            if p.timer > 10 then
                p.alpha = max(p.alpha - 5, 0)
                if p.alpha == 0 then
                    table.remove(self.particle, i)
                end
            end
            p.timer = p.timer + 1
        end
        self.bound = (#self.particle == 0) and (self.timer > 30)

    end
    function l:render_new()
        bent_laser.render(self)
        for _, p in ipairs(self.particle) do
            SetImageState("bright", "mul+add", p.alpha, p.r, p.g, p.b)
            Render("bright", p.x, p.y, 0, 10 / 150)
        end
    end
    return l
end
function ParticleLaserLine(pR, pG, pB, x, y, col, v, a, GrowTime, Width, Scale, Head, nosound)
    local l = Create.laser_line(x, y, col, v, a, GrowTime, Width, Scale, Head, nosound)
    l.particle = {}
    l.pcol = { pR, pG, pB }
    function l:frame_new()
        laser.frame(self)
        local len = self.l1 + self.l2 + self.l3
        local hx, hy = self.x + cos(self.rot) * len, self.y + sin(self.rot) * len
        if self.timer < 90 then
            local _a = ran:Float(0, 360)
            local _v = ran:Float(3, 6)
            table.insert(self.particle, {
                x = hx, y = hy,
                vx = cos(_a) * _v, vy = sin(_a) * _v,
                alpha = ran:Float(200, 250), timer = 0,
                r = self.pcol[1], g = self.pcol[2], b = self.pcol[3]
            })
        end
        local p
        for i = #self.particle, 1, -1 do
            p = self.particle[i]
            p.x = p.x + p.vx
            p.y = p.y + p.vy
            p.vx = p.vx - p.vx * 0.04
            p.vy = p.vy - p.vy * 0.04
            if p.timer > 10 then
                p.alpha = max(p.alpha - 5, 0)
                if p.alpha == 0 then
                    table.remove(self.particle, i)
                end
            end
            p.timer = p.timer + 1
        end
        self.bound = (#self.particle == 0) and (self.timer > 30)

    end
    function l:render_new()
        laser.render(self)
        for _, p in ipairs(self.particle) do
            SetImageState("bright", "mul+add", p.alpha, p.r, p.g, p.b)
            Render("bright", p.x, p.y, 0, 10 / 150)
        end
    end
    return l
end

